Method.Source:
    /// <summary>
    /// get the Image corresponding to the Logo type
    /// </summary>
    /// <param name = "_companyInfo">Company info</param>
    /// <param name = "_companyInfoType">Company image type</param>
    /// <returns>Image</returns>
    public static Image metGetImage(CompanyInfo _companyInfo)
    {
        Image   image;
        CompanyImage companyImage;

        companyImage = CompanyImage::findByRecord(_companyInfo);
                    
        if(companyImage && companyImage.HasImage)
        {
            image = new Image();
            image.setData(companyImage.Image);
        }

        return image;
    }
